 const rover=new T.Group(),chassis=new T.Mesh(new T.BoxGeometry(1.8,.7,3),new T.MeshBasicMaterial({color:'#f6ce42'}));chassis.position.y=.8;rover.add(chassis);const top=new T.Mesh(new T.BoxGeometry(1.4,.5,1.4),new T.MeshBasicMaterial({color:'#294c6b'}));top.position.y=1.4;rover.add(top);
