export async function timelines(label,orbit=true){
 const f=await setup(label),runs=[];try{
 for(const mounted of [false,true])for(const startId of [0,1])for(const repetition of [0,1]){
  const start={positionWorldMetersXYZ:[startId*8,.03,startId*6],facingYawRadians:Math.PI+startId*.4,...(label!=='old'?{cameraViewId:'third-person'}:{}),humanoid:mounted?{vehicleInstanceId:'rover',mounted:true}:{}};
  await f.port.prepareSegment(start,{widthPixels:1000,heightPixels:700});const samples=[];
  for(let tick=0;tick<120;tick++){
   const input={humanoid:{...f.SDK.humanoid.emptyInput(),forward:tick<100?1:0,steer:mounted&&tick>=60?.2:0,jump:!mounted&&tick===30,brake:mounted&&tick>=100},cameraYawRatio:orbit&&tick>=20&&tick<40?.2:0};
   await f.port.advance(input,1);
   // A repeated run varies presentation observation count without advancing the owner.
   if(repetition===1){f.observer.withPresentation(()=>f.renderer.render(f.scene,f.camera));if(tick%2===0)f.observer.withPresentation(()=>f.renderer.render(f.scene,f.camera));}
   samples.push({input,state:f.sample()});
  }
  runs.push({mounted,startId,repetition,start,samples});f.port.release();
 }
 return {runs,spec:f.spec,map:f.map,configuration:label!=='old'?f.world.inspectCamera().document:f.world.humanoid.inspectConfiguration(),device:{userAgent:navigator.userAgent,hardwareConcurrency:navigator.hardwareConcurrency}};
 }finally{f.world.dispose();f.renderer.dispose();}
}

