import json,math,pathlib
root=pathlib.Path('.codex-tmp/camera-r1');data={k:json.loads((root/f'{k}-timelines.json').read_text()) for k in ['old','new']}
def distance(a,b):return math.dist(a,b)
def angular(a,b):return 2*math.acos(min(1,abs(sum(x*y for x,y in zip(a,b)))/(math.sqrt(sum(x*x for x in a))*math.sqrt(sum(x*x for x in b)))))
def compare(a,b):
 out=dict(entityPositionMeters=0,entityVelocityMetersPerSecond=0,cameraPositionMeters=0,cameraAngleRadians=0,vehiclePositionMeters=0,actionMismatches=0)
 for x,y in zip(a['samples'],b['samples']):
  x=x['state'];y=y['state']
  for e,f in zip(x['entities'],y['entities']):
   out['entityPositionMeters']=max(out['entityPositionMeters'],distance(e['positionWorldMetersXYZ'],f['positionWorldMetersXYZ']))
   out['entityVelocityMetersPerSecond']=max(out['entityVelocityMetersPerSecond'],distance(e['motion']['velocityWorldMetersPerSecondXYZ'],f['motion']['velocityWorldMetersPerSecondXYZ']))
  out['cameraPositionMeters']=max(out['cameraPositionMeters'],distance(x['camera']['position'],y['camera']['position']))
  out['cameraAngleRadians']=max(out['cameraAngleRadians'],angular(x['camera']['quaternion'],y['camera']['quaternion']))
  out['vehiclePositionMeters']=max(out['vehiclePositionMeters'],distance(x['vehicle']['position'],y['vehicle']['position']))
  out['actionMismatches']+=x['action']!=y['action']
 return out
report={'repeat':{},'oldNew':[]}
for label,d in data.items():
 report['repeat'][label]=[]
 for i in [0,2,4,6]:
  c=compare(d['runs'][i],d['runs'][i+1]);report['repeat'][label].append(c)
  assert c['entityPositionMeters']<1e-9 and c['entityVelocityMetersPerSecond']<1e-9 and c['cameraPositionMeters']<1e-9 and c['cameraAngleRadians']<1e-7 and c['actionMismatches']==0,(label,i,c)
for i in [0,2,4,6]:
 a=data['old']['runs'][i];b=data['new']['runs'][i];c=compare(a,b);c.update(mounted=a['mounted'],startId=a['startId']);report['oldNew'].append(c)
report['states']=list(set(s['state']['action']['state'] for s in data['new']['runs'][0]['samples']))
(root/'comparison.json').write_text(json.dumps(report,indent=2));print(json.dumps(report,indent=2))

